<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { admin, err, type ModelSettings, type ProbeResult, type Run, type Source, type Usage } from "./api";
import { adminRequestGeneration, recordedUsage, usageValue } from "./admin-state";
import { idempotentSubmission } from "./submission";

const authenticated = ref(false), csrf = ref(""), expiresAt = ref(""), password = ref(""), activeTab = ref<"sources" | "runs" | "model">("sources");
const loginLoading = ref(false), loginError = ref<ReturnType<typeof err>>(), notice = ref("");
const sources = ref<Source[]>([]), runs = ref<Run[]>([]), model = ref<ModelSettings>(), usage = ref<Usage>();
const loading = ref(false), actionId = ref(""), pageError = ref<ReturnType<typeof err>>(), modelError = ref<ReturnType<typeof err>>();
const sourceDraft = ref({ name: "", feed_url: "", channel_type: "rss" }), editingId = ref<string | null>(null), editDraft = ref({ name: "", feed_url: "" });
const selectedSourceIds = ref<string[]>([]), apiKey = ref(""), maxTokens = ref(1024), modelEnabled = ref(false), testResult = ref(""), submission = idempotentSubmission();
const requests = adminRequestGeneration();
const busy = computed(() => Boolean(actionId.value) || loading.value);
const selectableSources = computed(() => sources.value.filter((source) => source.enabled && source.channel_type === "rss"));
const formatTime = (value?: string | null) => value ? new Intl.DateTimeFormat("zh-CN", { dateStyle: "short", timeStyle: "short" }).format(new Date(value)) : "—";
const healthLabel = (value: string) => ({ healthy: "健康", rate_limited: "受限", unverified: "未验证", degraded: "异常", failed: "失败" }[value.toLowerCase()] ?? `未知（${value}）`);
const purposeLabel = (value: string) => ({ connectivity: "连接检查", completion: "回答测试", extraction: "内容提取", embedding: "向量生成" }[value.toLowerCase()] ?? `其他用途（${value}）`);
const ledgerStatusLabel = (value: string) => ({ success: "成功", succeeded: "成功", failed: "失败", pending: "等待中", unavailable: "不可用" }[value.toLowerCase()] ?? `未知（${value}）`);
function clearPrivateState() { csrf.value = ""; expiresAt.value = ""; password.value = ""; sources.value = []; runs.value = []; model.value = undefined; usage.value = undefined; sourceDraft.value = { name: "", feed_url: "", channel_type: "rss" }; editDraft.value = { name: "", feed_url: "" }; editingId.value = null; selectedSourceIds.value = []; apiKey.value = ""; testResult.value = ""; pageError.value = undefined; modelError.value = undefined; notice.value = ""; }
function lock(message?: string) { requests.invalidate(); authenticated.value = false; loginLoading.value = false; loading.value = false; actionId.value = ""; clearPrivateState(); if (message) loginError.value = { code: "UNAUTHORIZED", message, status: 401 }; }
function handle(e: unknown, target = pageError) { const problem = err(e); if (problem.status === 401) lock("会话已过期，请重新输入管理口令。"); else target.value = problem; }
function current(generation: number) { return authenticated.value && requests.current(generation); }
async function restore() { loginLoading.value = true; const generation = requests.capture(); try { const session = await admin.session(); if (!requests.current(generation)) return; authenticated.value = session.authenticated; csrf.value = session.csrf_token ?? ""; expiresAt.value = session.expires_at ?? ""; if (session.authenticated && csrf.value) await loadAll(); } catch (e) { if (requests.current(generation)) handle(e, loginError); } finally { if (requests.current(generation)) loginLoading.value = false; } }
async function login() { if (!password.value || loginLoading.value) return; loginLoading.value = true; loginError.value = undefined; const generation = requests.capture(); try { const session = await admin.session(password.value); password.value = ""; if (!requests.current(generation)) return; if (!session.authenticated || !session.csrf_token) { lock("管理口令无效。"); return; } authenticated.value = true; csrf.value = session.csrf_token; expiresAt.value = session.expires_at ?? ""; await loadAll(); } catch (e) { password.value = ""; if (requests.current(generation)) handle(e, loginError); } finally { if (requests.current(generation)) loginLoading.value = false; } }
async function loadAll() { if (!authenticated.value) return; loading.value = true; pageError.value = undefined; modelError.value = undefined; const generation = requests.capture(); try { const [sourceResult, runResult, settings, usageResult] = await Promise.all([admin.sources(), admin.runs(), admin.model(), admin.usage()]); if (!current(generation)) return; sources.value = sourceResult.items; runs.value = runResult.items; model.value = settings; usage.value = usageResult; maxTokens.value = settings.max_tokens; modelEnabled.value = settings.enabled; selectedSourceIds.value = selectedSourceIds.value.filter((id) => sourceResult.items.some((source) => source.id === id && source.enabled && source.channel_type === "rss")); } catch (e) { if (current(generation)) handle(e); } finally { if (current(generation)) loading.value = false; } }
async function createSource() { if (busy.value || !sourceDraft.value.name.trim() || !sourceDraft.value.feed_url.trim()) return; actionId.value = "create"; const generation = requests.capture(); try { await admin.createSource(csrf.value, { ...sourceDraft.value, name: sourceDraft.value.name.trim(), feed_url: sourceDraft.value.feed_url.trim() }); if (!current(generation)) return; sourceDraft.value = { name: "", feed_url: "", channel_type: "rss" }; notice.value = "来源已添加，默认处于停用状态。"; await loadAll(); } catch (e) { if (current(generation)) handle(e); } finally { if (current(generation)) actionId.value = ""; } }
function beginEdit(source: Source) { if (!busy.value) { editingId.value = source.id; editDraft.value = { name: source.name, feed_url: source.feed_url }; } }
async function saveSource(source: Source) { if (busy.value) return; actionId.value = `save-${source.id}`; const generation = requests.capture(); try { await admin.updateSource(csrf.value, source.id, editDraft.value); if (!current(generation)) return; editingId.value = null; notice.value = "来源已保存。"; await loadAll(); } catch (e) { if (current(generation)) handle(e); } finally { if (current(generation)) actionId.value = ""; } }
async function toggleSource(source: Source) { if (busy.value) return; actionId.value = `toggle-${source.id}`; const generation = requests.capture(); try { await admin.updateSource(csrf.value, source.id, { enabled: !source.enabled }); if (!current(generation)) return; notice.value = source.enabled ? "来源已停用。" : "来源已启用。"; await loadAll(); } catch (e) { if (current(generation)) handle(e); } finally { if (current(generation)) actionId.value = ""; } }
async function probe(source: Source) { if (busy.value) return; actionId.value = `probe-${source.id}`; const generation = requests.capture(); try { const result: ProbeResult = await admin.probe(csrf.value, source.id); if (!current(generation)) return; notice.value = `${source.name}：${result.message}${result.items_found === undefined ? "" : `（发现 ${result.items_found} 项）`}`; await loadAll(); } catch (e) { if (current(generation)) handle(e); } finally { if (current(generation)) actionId.value = ""; } }
function toggleSelection(id: string, checked: boolean) { selectedSourceIds.value = checked ? [...selectedSourceIds.value, id] : selectedSourceIds.value.filter((value) => value !== id); }
async function startIngest() { if (busy.value || !selectedSourceIds.value.length) return; const key = submission.begin(); if (!key) return; actionId.value = "ingest"; const generation = requests.capture(); try { const result = await admin.start(csrf.value, selectedSourceIds.value, key); submission.finish(true); if (!current(generation)) return; notice.value = `已接受采集请求：${result.run_id}`; const response = await admin.runs(); if (current(generation)) runs.value = response.items; } catch (e) { submission.finish(false); if (current(generation)) handle(e); } finally { if (current(generation)) actionId.value = ""; } }
async function saveModel() { if (busy.value) return; actionId.value = "model-save"; modelError.value = undefined; const generation = requests.capture(); try { const payload: { api_key?: string; enabled: boolean; max_tokens: number } = { enabled: modelEnabled.value, max_tokens: maxTokens.value }; if (apiKey.value) payload.api_key = apiKey.value; const saved = await admin.saveModel(csrf.value, payload); if (!current(generation)) return; apiKey.value = ""; model.value = saved; notice.value = "模型设置已保存。"; } catch (e) { if (current(generation)) handle(e, modelError); } finally { if (current(generation)) actionId.value = ""; } }
async function testModel(kind: "connectivity" | "completion") { if (busy.value) return; actionId.value = `test-${kind}`; testResult.value = ""; const generation = requests.capture(); try { const result = await admin.testModel(csrf.value, kind); if (!current(generation)) return; testResult.value = `${result.ok ? "通过" : "未通过"}：${result.message}${result.usage ? ` · ${usageValue(result.usage.total_tokens)} tokens` : ""}`; const resultUsage = await admin.usage(); if (current(generation)) usage.value = resultUsage; } catch (e) { if (current(generation)) handle(e, modelError); } finally { if (current(generation)) actionId.value = ""; } }
async function logout() { if (busy.value) return; actionId.value = "logout"; loginError.value = undefined; const generation = requests.capture(); try { await admin.logout(csrf.value); if (!requests.current(generation)) return; lock(); } catch (e) { if (requests.current(generation)) pageError.value = { ...err(e), message: "退出未完成，当前会话仍有效，请重试。" }; } finally { if (requests.current(generation)) actionId.value = ""; } }
onMounted(() => { void restore(); });
</script>
<template>
  <section class="admin-page"><div class="admin-heading"><div><h1 class="page-title">管理员后台</h1><p class="page-subtitle">来源、采集与模型服务只在受保护会话中可用。</p></div><button v-if="authenticated" type="button" class="admin-logout" title="退出管理员后台" aria-label="退出管理员后台" :disabled="busy" @click="logout">{{ actionId === "logout" ? "退出中…" : "退出" }}</button></div><p v-if="notice" class="admin-notice" aria-live="polite">{{ notice }}</p>
    <section v-if="!authenticated" class="admin-lock card" aria-labelledby="admin-lock-title"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10" width="14" height="10" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v2"/></svg><div><h2 id="admin-lock-title">需要管理员会话</h2><p class="meta">输入管理口令以开启当前浏览器会话。口令不会保存在浏览器存储中。</p></div><form class="admin-login" @submit.prevent="login"><label>管理口令<input v-model="password" class="control" type="password" autocomplete="current-password" :disabled="loginLoading" /></label><button type="submit" :disabled="loginLoading || !password">{{ loginLoading ? "验证中…" : "进入后台" }}</button></form><div v-if="loginError" class="error admin-feedback" role="alert">{{ loginError.message }}</div></section>
    <template v-else><p class="meta admin-session">会话有效至 {{ formatTime(expiresAt) }}。退出或过期后需重新验证。</p><div class="admin-tabs" role="tablist" aria-label="后台管理区"><button :class="{ active: activeTab === 'sources' }" role="tab" :aria-selected="activeTab === 'sources'" :disabled="busy" @click="activeTab = 'sources'">来源</button><button :class="{ active: activeTab === 'runs' }" role="tab" :aria-selected="activeTab === 'runs'" :disabled="busy" @click="activeTab = 'runs'">采集记录</button><button :class="{ active: activeTab === 'model' }" role="tab" :aria-selected="activeTab === 'model'" :disabled="busy" @click="activeTab = 'model'">模型设置</button></div><div v-if="pageError" class="error admin-feedback" role="alert">{{ pageError.message }} <button type="button" :disabled="busy" @click="loadAll">重试</button></div><p v-if="loading" class="admin-skeleton" aria-live="polite">正在同步管理数据…</p>
      <section v-if="activeTab === 'sources' && !loading" class="admin-stack" aria-label="来源管理"><form class="card admin-form" @submit.prevent="createSource"><div><h2>添加 RSS 来源</h2><p class="meta">新来源默认停用；探测成功后再开启采集。</p></div><label>名称<input v-model="sourceDraft.name" class="control" maxlength="160" :disabled="busy" /></label><label>订阅地址<input v-model="sourceDraft.feed_url" class="control" type="url" maxlength="2048" placeholder="https://…/feed.xml" :disabled="busy" /></label><button type="submit" :disabled="busy || !sourceDraft.name || !sourceDraft.feed_url">{{ actionId === "create" ? "添加中…" : "添加来源" }}</button></form><section class="card"><div class="admin-section-title"><div><h2>来源健康</h2><p class="meta">{{ sources.length }} 个来源。</p></div><button type="button" title="刷新来源状态" aria-label="刷新来源状态" :disabled="busy" @click="loadAll">刷新</button></div><p v-if="!sources.length" class="empty meta">暂无来源。添加一个 RSS 地址后可在此探测和启用。</p><article v-for="source in sources" :key="source.id" class="source-row"><div class="source-main"><template v-if="editingId === source.id"><label>名称<input v-model="editDraft.name" class="control" maxlength="160" :disabled="busy" /></label><label>订阅地址<input v-model="editDraft.feed_url" class="control" type="url" maxlength="2048" :disabled="busy" /></label></template><template v-else><strong>{{ source.name }}</strong><a :href="source.feed_url" target="_blank" rel="noreferrer">{{ source.feed_url }}</a></template><p class="meta"><span class="health" :class="source.health" :title="source.health">{{ healthLabel(source.health) }}</span> · 连续失败 {{ source.consecutive_failures }} · 最近探测 {{ formatTime(source.last_checked_at) }} · 最近成功 {{ formatTime(source.last_success_at) }}<span v-if="source.cooldown_until"> · 冷却至 {{ formatTime(source.cooldown_until) }}</span></p><p v-if="!source.editable" class="meta">内置采集适配：名称和订阅地址由系统维护。</p></div><div class="source-actions"><template v-if="editingId === source.id"><button type="button" :disabled="busy" @click="saveSource(source)">{{ actionId === `save-${source.id}` ? "保存中…" : "保存" }}</button><button type="button" :disabled="busy" @click="editingId = null">取消</button></template><template v-else><button v-if="source.editable" type="button" title="编辑来源" :aria-label="`编辑 ${source.name}`" :disabled="busy" @click="beginEdit(source)">编辑</button><button type="button" :disabled="busy" :title="`探测 ${source.name}`" @click="probe(source)">{{ actionId === `probe-${source.id}` ? "探测中…" : "探测" }}</button><button type="button" :disabled="busy" @click="toggleSource(source)">{{ source.enabled ? "停用" : "启用" }}</button></template></div></article></section></section>
      <section v-if="activeTab === 'runs' && !loading" class="admin-stack"><section class="card"><div class="admin-section-title"><div><h2>采集记录</h2><p class="meta">手动采集仅提交下方明确勾选的已启用 RSS 来源。归档适配由定时回填处理，不能在此提交。</p></div><button type="button" :disabled="busy || !selectedSourceIds.length" @click="startIngest">{{ actionId === "ingest" ? "提交中…" : "开始采集" }}</button></div><fieldset class="source-picker"><legend>选择要采集的 RSS 来源</legend><p v-if="!selectableSources.length" class="meta">没有可手动采集的已启用 RSS 来源。</p><label v-for="source in selectableSources" :key="source.id"><input type="checkbox" :checked="selectedSourceIds.includes(source.id)" :disabled="busy" @change="toggleSelection(source.id, ($event.target as HTMLInputElement).checked)" />{{ source.name }}</label></fieldset><p v-if="!runs.length" class="empty meta">尚无采集记录。</p><div v-else class="runs-table"><article v-for="run in runs" :key="run.id"><strong>{{ run.status }}</strong><span>{{ formatTime(run.started_at) }}</span><span class="tabular">发现 {{ run.found }} · 候选 {{ run.candidates }} · 版本 {{ run.versions }} · 发布 {{ run.kept }}</span><span class="tabular">解析失败 {{ run.parser_failures }} · 任务失败 {{ run.failed_jobs }}</span><span v-if="run.error_summary" class="run-error">{{ run.error_summary }}</span></article></div></section></section>
      <section v-if="activeTab === 'model' && !loading && model" class="admin-stack"><section class="card admin-model"><div><h2>DeepSeek / Flash</h2><p class="meta">{{ model.provider }} · {{ model.model }} · {{ model.base_url }}</p></div><form class="admin-form" @submit.prevent="saveModel"><label>新 API 密钥<input v-model="apiKey" class="control" type="password" autocomplete="new-password" placeholder="留空以保留当前密钥" :disabled="busy" /></label><label>最大输出 tokens<input v-model.number="maxTokens" class="control" type="number" min="1" max="2000" :disabled="busy" /></label><label class="toggle"><input v-model="modelEnabled" type="checkbox" :disabled="busy" />启用模型服务</label><p class="meta">当前密钥{{ model.configured ? "已配置" : "未配置" }}，系统不会回显密钥。</p><button type="submit" :disabled="busy">{{ actionId === "model-save" ? "保存中…" : "保存设置" }}</button></form><div class="model-tests"><div><h3>连接检查</h3><p class="meta">使用已保存的配置验证服务连通与鉴权，不会生成回答。</p><button type="button" :disabled="busy" @click="testModel('connectivity')">{{ actionId === "test-connectivity" ? "检查中…" : "检查连接" }}</button></div><div><h3>回答测试</h3><p class="meta">使用已保存的配置请求 Flash 生成一条简短回答，并记录 token 用量。</p><button type="button" :disabled="busy" @click="testModel('completion')">{{ actionId === "test-completion" ? "测试中…" : "测试回答" }}</button></div></div><p v-if="testResult" class="admin-notice" aria-live="polite">{{ testResult }}</p><div v-if="modelError" class="error admin-feedback" role="alert">{{ modelError.message }}</div></section><section class="card"><h2>模型用量</h2><p class="meta">截至 {{ formatTime(usage?.as_of) }}</p><p v-if="!usage?.items.length" class="empty meta">暂无可记录的模型调用。</p><div v-else class="usage-table"><article v-for="item in usage.items" :key="`${item.purpose}-${item.status}`"><strong :title="item.purpose">{{ purposeLabel(item.purpose) }}</strong><span :title="item.status">{{ ledgerStatusLabel(item.status) }} · {{ item.calls }} 次</span><span class="tabular">输入 {{ usageValue(item.input_tokens) }} · 输出 {{ usageValue(item.output_tokens) }} · 合计 {{ usageValue(item.total_tokens) }}</span><span>{{ recordedUsage(item.usage_recorded) }}</span></article></div></section></section>
    </template></section>
</template>